from calendar_store import latest

def render(records, lo, hi, asof):
    if lo >= hi:
        return []
    selected = latest(records, asof)
    segs = []
    for key, (rev, start, end, value) in selected.items():
        if value is None:
            continue
        s = max(start, lo)
        e = min(end, hi)
        if s < e:
            segs.append((s, e, value, rev, key))
    if not segs:
        return []
    bounds = {lo, hi}
    for s, e, _, _, _ in segs:
        bounds.add(s)
        bounds.add(e)
    points = sorted(bounds)
    segments = []
    for i in range(len(points) - 1):
        a, b = points[i], points[i + 1]
        if a >= b:
            continue
        best_rev = None
        best_key = None
        best_val = None
        for s, e, v, rev, key in segs:
            if s < b and e > a:
                if best_rev is None or rev > best_rev or (rev == best_rev and key < best_key):
                    best_rev = rev
                    best_key = key
                    best_val = v
        if best_val is None:
            continue
        segments.append([a, b, best_val])
    merged = []
    for seg in segments:
        if merged and merged[-1][2] == seg[2] and merged[-1][1] == seg[0]:
            merged[-1][1] = seg[1]
        else:
            merged.append([seg[0], seg[1], seg[2]])
    return merged

def evaluate(records, windows):
    return [render(records, lo, hi, t) for lo, hi, t in windows]
